import React from "react";
import { Switch, Route, Redirect } from "react-router-dom";

// components

import AdminNavbar from "components/Navbars/AdminNavbar.js";
import Sidebar from "components/Sidebar/Sidebar.js";
import HeaderStats from "components/Headers/HeaderStats.js";
import FooterAdmin from "components/Footers/FooterAdmin.js";

// views

import Dashboard from "views/admin/Dashboard.js";
import Agence from "views/admin/Agence.js";
import Personnes from "views/admin/Personnes.js";
import Voiture from "views/admin/Voiture.js";
import AddVoiture from "views/admin/AddVoiture";
import Client from "views/admin/Client";
import Reservation from "views/admin/Reservation";
import AddAgence from "views/admin/AddAgence";
import AddAdmin from "views/admin/AddAdmin";
import CardUpdateVoiture from "views/admin/UpdateVoiture";

export default function Admin() {
  return (
    <>
      <Sidebar />
      <div className="relative md:ml-64 bg-blueGray-100">
        <AdminNavbar />
        {/* Header */}
        <HeaderStats />
        <div className="px-4 md:px-10 mx-auto w-full -m-24">
          <Switch>
            <Route path="/admin/dashboard" exact component={Dashboard} />
            <Route path="/admin/Agence" exact component={Agence} />
            <Route path="/admin/Personnes" exact component={Personnes} />
            <Route path="/admin/Voiture" exact component={Voiture} />
            <Route path="/admin/Client" exact component={Client} />
            <Route path="/admin/AddVoiture" exact component={AddVoiture} />
            <Route path="/admin/AddAgence" exact component={AddAgence} />
            <Route path="/admin/AddAdmin" exact component={AddAdmin} />
            <Route path="/admin/Reservation" exact component={Reservation} />
            <Route path="/admin/AddAdmin/:agenceId" element={CardAddAdmin} />
            <Route path="/admin/UpdateVoiture/:id" component={CardUpdateVoiture} />


            <Redirect from="/admin" to="/admin/dashboard" />
          </Switch>
          <FooterAdmin />
        </div>
      </div>
    </>
  );
}
